// Pure code: one marked block in an ignore file. A line outside the markers is never changed, moved, or dropped.

export const BLOCK_START =
	"# >>> claudetto: generated by /claudetto:setup, edit outside this block";
export const BLOCK_END = "# <<< claudetto";

const LEADING_BANG = /^!/;
const LEADING_SLASH = /^\//;
const TRAILING_SLASH = /\/$/;
const TRAILING_NEWLINE = /\n$/;

/** The path a line names, with a negation, a leading slash, and a trailing slash removed; `undefined` for a comment or a blank. */
const pathOf = (line: string): string | undefined => {
	const text = line.trim();
	if (text === "" || text.startsWith("#")) {
		return undefined;
	}
	return text
		.replace(LEADING_BANG, "")
		.replace(LEADING_SLASH, "")
		.replace(TRAILING_SLASH, "");
};

const namedBy = (lines: readonly string[]): Set<string> => {
	const named = new Set<string>();
	for (const line of lines) {
		const path = pathOf(line);
		if (path !== undefined) {
			named.add(path);
		}
	}
	return named;
};

const appended = (text: string, block: readonly string[]): string => {
	const tail = block.join("\n");
	if (text === "") {
		return `${tail}\n`;
	}
	const ended = text.endsWith("\n") ? text : `${text}\n`;
	const gap = ended === "\n" || ended.endsWith("\n\n") ? "" : "\n";
	return `${ended}${gap}${tail}\n`;
};

/**
 * The file with its block set to `lines`, less any path the lines outside the block already name, because the last matching
 * line wins and an appended line would undo a negation. A file with no block gets one after a blank line; an unclosed block is
 * left alone, since its end is unknown.
 */
const applyLf = (
	current: string | undefined,
	lines: readonly string[],
): string | undefined => {
	const text = current ?? "";
	const parts = text.split("\n");
	const start = parts.indexOf(BLOCK_START);
	const end = start === -1 ? -1 : parts.indexOf(BLOCK_END, start + 1);
	if (start !== -1 && end < 0) {
		return current;
	}
	const outside =
		start === -1 ? parts : [...parts.slice(0, start), ...parts.slice(end + 1)];
	const named = namedBy(outside);
	const kept = [
		...new Set(lines.filter((line) => !named.has(pathOf(line) ?? line))),
	];
	const block = [BLOCK_START, ...kept, BLOCK_END];
	if (start !== -1) {
		return [...parts.slice(0, start), ...block, ...parts.slice(end + 1)].join(
			"\n",
		);
	}
	return kept.length === 0 ? current : appended(text, block);
};

/** A CRLF file is read and written in CRLF, so its markers are found again on a rerun. */
export const applyBlock = (
	current: string | undefined,
	lines: readonly string[],
): string | undefined =>
	current?.includes("\r\n") === true
		? applyLf(current.replaceAll("\r\n", "\n"), lines)?.replaceAll("\n", "\r\n")
		: applyLf(current, lines);

const linesOfText = (text: string | undefined): string[] =>
	text === undefined || text === ""
		? []
		: text.replace(TRAILING_NEWLINE, "").split("\n");

/** The lines that differ, as `-` and `+` under a header; empty when nothing changes. */
export const diffOf = (
	path: string,
	before: string | undefined,
	after: string,
): string => {
	if (before === after) {
		return "";
	}
	const old = linesOfText(before);
	const next = linesOfText(after);
	let head = 0;
	while (head < old.length && head < next.length && old[head] === next[head]) {
		head++;
	}
	let tail = 0;
	while (
		tail < old.length - head &&
		tail < next.length - head &&
		old[old.length - 1 - tail] === next[next.length - 1 - tail]
	) {
		tail++;
	}
	return [
		`+++ ${path}`,
		...old.slice(head, old.length - tail).map((line) => `-${line}`),
		...next.slice(head, next.length - tail).map((line) => `+${line}`),
	].join("\n");
};
